#define pi     3.14159265

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float b=20.;
    int n=12;

    vec2 uv = fragCoord/iResolution.y-vec2(0.5*iResolution.x/iResolution.y,0.5);
    int n2=8;
    float N=float(n2)*0.5/pi;
    //kaleidoscopic effect
    uv=vec2(cos(fract(atan(uv.y,uv.x)*N)/N)*length(uv),
            sin(fract(atan(uv.y,uv.x)*N)/N)*length(uv));

    vec2 uv2= fract(float(n)*uv);


    float x=1.-1.98*length(uv2+vec2(-0.5,-0.5));

    float a=2.+sin(floor(float(n)*uv.y)*0.7985+floor(float(n)*uv.x)*0.124+iTime*2.58)+sin(floor(float(n)*uv.x)*0.5665-iTime*3.7865)+0.5*sin(floor(float(n)*uv.x)*0.1-iTime*1.);
    a*=0.3;

    x=clamp(x,0.0,1.);
    vec2 uv3=2.*(uv2+vec2(-0.5,-0.5));

    a+=1.*(2.-clamp(8.*length(iMouse.xy-(fragCoord-uv2*iResolution.y/(float(n))))/iResolution.y,0.,2.));

    uv3=vec2(
        cos(x*pi*a)*uv3.x - sin(x*pi*a)*uv3.y, 
        sin(x*pi*a)*uv3.x + cos(x*pi*a)*uv3.y
    );
    vec2 uv4=vec2(sqrt(2.)/2.*(uv3.x-uv3.y),sqrt(2.)/2.*(uv3.x+uv3.y));
    vec3 col = vec3(0.4,0,0.5)*log(2.-length(uv3))/log(0.2);

    if(((uv3.y<=1./(b*uv3.x)) && (uv3.y>=-1./(b*uv3.x))) ||((uv3.y>=1./(b*uv3.x)) && (uv3.y<=-1./(b*uv3.x))))
    {
        col=vec3(0.76,0.4,0.9)*clamp((length(uv3)+0.1),0.0,1.);
    }

    //col=uv.x*vec3(1,1,1);
    // Output to screen
    fragColor = vec4(col,1.0);
}
